// store/modules/product.js
import { getAllProducts, createProduct, getProductById, updateProduct, deleteProduct } from '@/services/productService.js';

const state = {
  products: [],
  product: null,
  error: null,
};

const mutations = {
  SET_PRODUCTS(state, products) {
    state.products = products;
  },
  SET_PRODUCT(state, product) {
    state.product = product;
  },
  SET_ERROR(state, error) {
    state.error = error;
  },
};

const actions = {
  async fetchProducts({ commit }) {
    try {
      const products = await getAllProducts(); // 调用服务获取所有产品
      commit('SET_PRODUCTS', products); // 提交到mutation更新状态
    } catch (error) {
      commit('SET_ERROR', error.message); // 处理错误
    }
  },

  async createNewProduct({ commit }, productData) {
    try {
      const newProduct = await createProduct(productData); // 调用服务创建新产品
      commit('SET_PRODUCT', newProduct); // 提交到mutation更新状态
    } catch (error) {
      commit('SET_ERROR', error.message); // 处理错误
    }
  },

  async fetchProductById({ commit }, id) {
    try {
      const product = await getProductById(id); // 调用服务获取特定产品
      commit('SET_PRODUCT', product); // 提交到mutation更新状态
    } catch (error) {
      commit('SET_ERROR', error.message); // 处理错误
    }
  },

  async updateProduct({ commit }, { id, updatedData }) {
    try {
      const updatedProduct = await updateProduct(id, updatedData); // 调用服务更新产品信息
      commit('SET_PRODUCT', updatedProduct); // 提交到mutation更新状态
    } catch (error) {
      commit('SET_ERROR', error.message); // 处理错误
    }
  },

  async deleteProduct({ commit }, id) {
    try {
      await deleteProduct(id); // 调用服务删除特定产品
      commit('SET_PRODUCTS', state.products.filter(product => product.id !== id)); // 更新状态，移除已删除的产品
    } catch (error) {
      commit('SET_ERROR', error.message); // 处理错误
    }
  },
};

const getters = {
  allProducts(state) {
    return state.products;
  },
  currentProduct(state) {
    return state.product;
  },
  error(state) {
    return state.error;
  },
};

export default {
  state,
  mutations,
  actions,
  getters,
};
